import io.github.djyking.harness.core.*;
import io.github.djyking.harness.core.Contracts.*;
import io.github.djyking.harness.core.testing.ScriptedModel;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.*;
public final class CancellationReproducer {
  public static void main(String[] args) {
    Actor actor=new Actor("proof-actor","proof-project",Set.of("*"));
    AtomicInteger calls=new AtomicInteger();
    AtomicBoolean cancelled=new AtomicBoolean();
    AtomicReference<Harness> owner=new AtomicReference<>();
    AtomicReference<String> id=new AtomicReference<>();
    ToolRegistry tools=new ToolRegistry();
    tools.register(new ToolDescriptor("proof/tool","proof_tool","Synthetic local effect","test","proof","1",Json.object().put("type","object"),new ToolPolicy(false,false,false,1,5000,Set.of())),(tool,input,context)->{calls.incrementAndGet();return ToolResult.success(input);});
    Telemetry telemetry=(context,operation,target)->{
      if(cancelled.compareAndSet(false,true)) owner.get().cancel(id.get(),actor);
      return Telemetry.noop().start(context,operation,target);
    };
    try(Harness harness=new Harness(new InMemoryRunStore(),new ScriptedModel(),tools,AccessPolicy.actorPermissions(),telemetry,Clock.systemUTC(),Duration.ofSeconds(30))) {
      owner.set(harness);
      harness.registerProgram("proof",run->run.results.containsKey("call")?new CompleteAction(run.results.get("call").value()):new ToolAction("call","proof","proof/tool",Json.object()));
      RunState run=harness.start(new ProgramDefinition("proof","1","proof",Json.object()),actor,List.of("proof/tool"),Budget.defaults(),Duration.ofMinutes(2),"proof-key");
      id.set(run.id);harness.tick(run.id);run=harness.tick(run.id);
      String phase=run.pending==null?"NONE":run.pending.phase.name();
      System.out.println(Json.write(Json.object().put("status",run.status.name()).put("phase",phase).put("calls",calls.get()).put("cancelRequested",run.cancelRequested).put("cancellationInjectedAfterBarrier",cancelled.get())));
      if(run.status!=RunStatus.CANCELLED||!phase.equals("PREPARED")||calls.get()!=0||!cancelled.get())System.exit(1);
    }
  }
}
